<?php
declare(strict_types=1);
require __DIR__.'/../api/life/store.php';require __DIR__.'/../api/life/accounts.php';require __DIR__.'/../api/life/ai.php';require __DIR__.'/../api/life/partners.php';require __DIR__.'/../api/life/reminders.php';require __DIR__.'/../api/life/public-quota.php';
$db=new PDO('sqlite::memory:');$db->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);$db->exec(file_get_contents(__DIR__.'/../api/life/schema.sql'));$owner=new LifeStore($db);$owner->initialize('test-only-owner-passphrase');$accounts=new LifeAccounts($db);$checks=0;
function check(bool $ok,string $message):void {global $checks;if(!$ok)throw new RuntimeException($message);$checks++;}
function rejects(callable $fn,int $status):void {try{$fn();}catch(LifeError $e){check($e->status===$status,'Status mismatch');return;}throw new RuntimeException('Expected rejection');}
$a=$accounts->signIn(['sub'=>'test-a','email'=>'a@example.com','name'=>'A','email_verified'=>true],'Europe/London');$b=$accounts->signIn(['sub'=>'test-b','email'=>'b@example.com','name'=>'B','email_verified'=>true]);$sa=new LifeStore($db,(int)$a['id']);$sb=new LifeStore($db,(int)$b['id']);
check(LifeAccounts::validPolicyVersions(LifeAccounts::PRIVACY_VERSION,LifeAccounts::TERMS_VERSION),'Current policy versions accepted');check(!LifeAccounts::validPolicyVersions('old',LifeAccounts::TERMS_VERSION),'Stale policy rejected');LifeAccounts::requirePolicyAcceptance(true,LifeAccounts::PRIVACY_VERSION,LifeAccounts::TERMS_VERSION);rejects(fn()=>LifeAccounts::requirePolicyAcceptance(false,LifeAccounts::PRIVACY_VERSION,LifeAccounts::TERMS_VERSION),422);rejects(fn()=>LifeAccounts::requirePolicyAcceptance(true,'old',LifeAccounts::TERMS_VERSION),422);$subject='google:'.hash('sha256','test-a');$accounts->acceptPolicies((int)$a['id'],$subject,LifeAccounts::PRIVACY_VERSION,LifeAccounts::TERMS_VERSION);$accepted=$db->prepare('SELECT privacy_version,terms_version,accepted_at FROM life_policy_acceptance WHERE account_id=? AND subject=?');$accepted->execute([$a['id'],$subject]);$record=$accepted->fetch(PDO::FETCH_ASSOC);check($record['privacy_version']===LifeAccounts::PRIVACY_VERSION&&$record['terms_version']===LifeAccounts::TERMS_VERSION&&$record['accepted_at']!=='','Policy acceptance stored against the correct account');rejects(fn()=>$accounts->acceptPolicies((int)$a['id'],$subject,'stale',LifeAccounts::TERMS_VERSION),422);
check($a['id']!==$b['id']&&$a['id']!==1,'Separate IDs');check($accounts->signIn(['sub'=>'test-a','email'=>'changed@example.com','name'=>'A','email_verified'=>true])['id']===$a['id'],'Stable Google subject');
$d=$sa->read();$d=$sa->mutate($d['version'],'task.save',['title'=>'Private A task','listId'=>$d['state']['lists'][0]['id']]);check(count($sb->read()['state']['tasks'])===0,'B cannot see A task');check(count($owner->read()['state']['tasks'])===0,'Legacy owner untouched');$task=$d['state']['tasks'][0]['id'];rejects(fn()=>$sb->mutate($sb->read()['version'],'task.rename',['id'=>$task,'title'=>'Cross account']),404);
$aa=new LifeAI($sa);$ab=new LifeAI($sb);$r=$aa->read();$aa->mutate($r['version'],'memory.save',['text'=>'Private memory']);check(count($ab->read()['state']['memories'])===0,'AI memory private');
$pa=new LifePartners($sa);$pb=new LifePartners($sb);$invite=$pa->invite('Partner A');check($pb->find($invite['id'])===null&&count($pb->list())===0,'Invites private');$pb->revoke($invite['id']);check(!$pa->find($invite['id'])['revoked'],'Cannot revoke another account invite');
$ra=new LifeReminders($sa);$rb=new LifeReminders($sb);$input=['endpoint'=>'https://fcm.googleapis.com/test-account','keys'=>['p256dh'=>str_repeat('A',87),'auth'=>str_repeat('B',22)]];$ra->subscribe($input);$rb->unsubscribe($input['endpoint']);$q=$db->prepare('SELECT COUNT(*) FROM life_push_subscriptions WHERE owner_id=?');$q->execute([$a['id']]);check((int)$q->fetchColumn()===1,'Push device remains owned by A');$rb->subscribe($input);check((int)$db->query('SELECT COUNT(*) FROM life_push_subscriptions')->fetchColumn()===2,'Same device separately scoped');
rejects(fn()=>$accounts->signIn(['sub'=>'unverified','email'=>'a@example.com','email_verified'=>false]),403);rejects(fn()=>$accounts->signIn(['sub'=>'test-a','email'=>'a@example.com','email_verified'=>true],linkOwner:true),409);$accounts->signIn(['sub'=>'owner-google','email'=>'owner@example.com','email_verified'=>true],linkOwner:true);check($accounts->find(1)['google_sub']==='owner-google','Explicit owner link');check($owner->owner()!==null,'Legacy credential preserved');
$quota=new LifePublicQuota($db);for($i=0;$i<50;$i++)$quota->reserve((int)$a['id']);rejects(fn()=>$quota->reserve((int)$a['id']),429);$quota->reserve(1);$quota->reserve((int)$b['id']);check(true,'Owner unaffected; B has independent allowance');
echo "$checks account isolation checks passed\n";
